#!/usr/bin/env python3
"""Regenerate the audio layout fixtures in this directory.

Every file starts from a synthetic 8 kHz, 0.1 s sine written by this script,
so nothing here carries third-party audio. The lossy and compressed variants
come from the encoders on the generating machine; the MP4 rewrite and the
APEv2 footer are done in-process so the fixtures exercise paths those
encoders never emit for small files.

Tools (override with environment variables of the same name):
  AFCONVERT=/usr/bin/afconvert   FLAC=/opt/homebrew/bin/flac
  LAME=/opt/homebrew/bin/lame    FFMPEG=/usr/local/bin/ffmpeg
"""
import math
import os
import struct
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
AFCONVERT = os.environ.get("AFCONVERT", "/usr/bin/afconvert")
FLAC = os.environ.get("FLAC", "/opt/homebrew/bin/flac")
LAME = os.environ.get("LAME", "/opt/homebrew/bin/lame")
FFMPEG = os.environ.get("FFMPEG", "/usr/local/bin/ffmpeg")
RATE = 8000
FRAMES = 800


def run(*cmd):
    subprocess.run([str(c) for c in cmd], check=True, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)


def write_tone(path, hz):
    pcm = b"".join(struct.pack("<h", int(8000 * math.sin(2 * math.pi * hz * i / RATE))) for i in range(FRAMES))
    fmt = struct.pack("<HHIIHH", 1, 1, RATE, RATE * 2, 2, 16)
    body = b"WAVE" + b"fmt " + struct.pack("<I", len(fmt)) + fmt + b"data" + struct.pack("<I", len(pcm)) + pcm
    path.write_bytes(b"RIFF" + struct.pack("<I", len(body)) + body)


def boxes(data, start=0, end=None):
    end = len(data) if end is None else end
    at = start
    while at + 8 <= end:
        size, kind = struct.unpack(">I4s", data[at:at + 8])
        header = 8
        if size == 1:
            size = struct.unpack(">Q", data[at + 8:at + 16])[0]
            header = 16
        elif size == 0:
            size = end - at
        yield at, size, header, kind
        at += size


CONTAINERS = {b"moov", b"trak", b"mdia", b"minf", b"stbl"}


def rewrite_co64(box, delta):
    """Return `box` (a moov subtree) with every stco turned into co64, offsets shifted by delta."""
    size, kind = struct.unpack(">I4s", box[:8])
    body = box[8:]
    if kind == b"stco":
        version_flags = body[:4]
        count = struct.unpack(">I", body[4:8])[0]
        offsets = struct.unpack(">%dI" % count, body[8:8 + 4 * count])
        new_body = version_flags + struct.pack(">I", count) + b"".join(struct.pack(">Q", o + delta) for o in offsets)
        return struct.pack(">I4s", 8 + len(new_body), b"co64") + new_body
    if kind in CONTAINERS:
        out = b""
        for at, child_size, header, _ in boxes(body):
            out += rewrite_co64(body[at:at + child_size], delta)
        return struct.pack(">I4s", 8 + len(out), kind) + out
    return box


def count_stco_entries(box):
    size, kind = struct.unpack(">I4s", box[:8])
    body = box[8:]
    if kind == b"stco":
        return struct.unpack(">I", body[4:8])[0]
    if kind in CONTAINERS:
        return sum(count_stco_entries(body[at:at + s]) for at, s, _, _ in boxes(body))
    return 0


def make_co64_m4a(src, dst):
    data = src.read_bytes()
    top = list(boxes(data))
    kinds = [k for _, _, _, k in top]
    assert kinds.index(b"moov") < kinds.index(b"mdat"), "rewrite assumes moov precedes mdat"
    # Every stco entry grows by 4 bytes and the mdat header by 8; chunk
    # offsets point into mdat, so both growths shift them.
    moov_at, moov_size, _, _ = next(b for b in top if b[3] == b"moov")
    delta = 4 * count_stco_entries(data[moov_at:moov_at + moov_size]) + 8
    out = b""
    for at, size, header, kind in top:
        box = data[at:at + size]
        if kind == b"moov":
            out += rewrite_co64(box, delta)
        elif kind == b"mdat":
            out += struct.pack(">I4sQ", 1, b"mdat", 16 + (size - header)) + box[header:]
        else:
            out += box
    dst.write_bytes(out)


def append_ape_footer(path, items):
    body = b""
    for key, value in items:
        encoded = value.encode()
        body += struct.pack("<II", len(encoded), 0) + key.encode() + b"\0" + encoded
    tag_size = len(body) + 32
    footer = b"APETAGEX" + struct.pack("<IIII", 2000, tag_size, len(items), 0) + b"\0" * 8
    path.write_bytes(path.read_bytes() + body + footer)


def main():
    tone = HERE / "tone.wav"
    write_tone(tone, 440.0)
    run(AFCONVERT, "-f", "AIFF", "-d", "BEI16", tone, HERE / "tone.aiff")
    run(AFCONVERT, "-f", "AIFC", "-d", "BEI16", tone, HERE / "tone.aifc")
    run(FLAC, "-s", "-f", "--no-padding", "-T", "TITLE=Pulp fixture", "-o", HERE / "tone.flac", tone)
    run(LAME, "--quiet", "-V", "9", "--id3v2-only", "--tt", "Pulp fixture", "--ta", "Pulp", tone, HERE / "tagged.mp3")
    append_ape_footer(HERE / "tagged.mp3", [("Title", "Pulp fixture"), ("Comment", "generated by Pulp")])
    second = HERE / "tone2.wav"
    write_tone(second, 660.0)
    run(FFMPEG, "-v", "error", "-y", "-fflags", "+bitexact", "-i", tone, "-c:a", "libvorbis", "-q:a", "0", HERE / "a.ogg")
    run(FFMPEG, "-v", "error", "-y", "-fflags", "+bitexact", "-i", second, "-c:a", "libvorbis", "-q:a", "0", HERE / "b.ogg")
    (HERE / "chained.ogg").write_bytes((HERE / "a.ogg").read_bytes() + (HERE / "b.ogg").read_bytes())
    run(AFCONVERT, "-f", "m4af", "-d", "aac", tone, HERE / "stco.m4a")
    make_co64_m4a(HERE / "stco.m4a", HERE / "co64.m4a")
    for scratch in ("tone.wav", "tone2.wav", "a.ogg", "b.ogg", "stco.m4a"):
        (HERE / scratch).unlink()
    for path in sorted(HERE.iterdir()):
        if path.suffix in (".aiff", ".aifc", ".flac", ".mp3", ".ogg", ".m4a"):
            size = path.stat().st_size
            assert size < 32 * 1024, f"{path.name} is {size} bytes"
            print(f"{path.name}\t{size}")


if __name__ == "__main__":
    sys.exit(main())
